using System.Data; using System.Globalization; using Avalonia; using Avalonia.Controls; using Avalonia.Layout; using Avalonia.Media; using ElectronicsStore.Data; using ElectronicsStore.Models; using ElectronicsStore.Services;
namespace ElectronicsStore.Views;
public partial class MainWindow : Window {
 readonly List<CartLine> cart=new(); bool busy;
 public MainWindow(){InitializeComponent();LoginPage();}
 TextBox Input(string hint,string text="")=>new(){Watermark=hint,Text=text,HorizontalAlignment=HorizontalAlignment.Stretch};
 TextBlock Text(string s)=>new(){Text=s,TextWrapping=TextWrapping.Wrap};
 Button Button(string title,Func<Task> action){var b=new Button{Content=title,Margin=new Thickness(0,0,8,5)};b.Click+=async(_,_)=>await Run(action);return b;}
 async Task Run(Func<Task> action){if(busy)return;busy=true;Navigation.IsEnabled=false;Page.IsEnabled=false;Message.Text="";try{await action();}catch(Exception ex){Message.Text=ex is Microsoft.Data.SqlClient.SqlException?"Ошибка базы данных. Проверьте сервер в connection.txt и допустимость данных. Подробности: "+ex.Message:ex.Message;}finally{busy=false;Navigation.IsEnabled=true;Page.IsEnabled=true;}}
 void Start(string title){Page.Children.Clear();Message.Text="";Identity.Text=Session.Current is {}u?$"{u.Name} • {u.Role}":"Гость";Navigation.Children.Clear();Navigation.Children.Add(Button("Каталог",Catalog));if(Session.Current!=null){Navigation.Children.Add(Button($"Корзина ({cart.Count})",Cart));Navigation.Children.Add(Button("Заказы",Orders));}if(Session.Manage){Navigation.Children.Add(Button("Товары",()=>ProductEditor(null)));Navigation.Children.Add(Button("Справочники",References));Navigation.Children.Add(Button("Отчёт",Report));}if(Session.Admin)Navigation.Children.Add(Button("Пользователи",Users));Navigation.Children.Add(Button("Сменить пользователя",()=>{Session.Logout();cart.Clear();LoginPage();return Task.CompletedTask;}));Page.Children.Add(new TextBlock{Text=title,FontSize=21,FontWeight=FontWeight.Bold});}
 void LoginPage(){Start("Вход в систему");Navigation.Children.Clear();var email=Input("Электронная почта");var password=Input("Пароль");password.PasswordChar='●';Page.Children.Add(email);Page.Children.Add(password);Page.Children.Add(Button("Войти",async()=>{Session.Login(await StoreService.Login(email.Text??"",password.Text??""));cart.Clear();await Catalog();}));Page.Children.Add(Button("Войти как гость",async()=>{Session.Logout();cart.Clear();await Catalog();}));Page.Children.Add(Text("Учебные учётные записи приведены в инструкции README_RU.md."));}
 async Task Catalog(){Start("Каталог товаров");var search=Input("Название или код товара");var cats=await StoreService.Choices("Categories");cats.Insert(0,new Choice(0,"Все категории"));var category=new ComboBox{ItemsSource=cats,SelectedIndex=0,MinWidth=200};var sort=new ComboBox{ItemsSource=new[]{"По названию","Сначала дешевле","Сначала дороже"},SelectedIndex=0,MinWidth=200};var list=new StackPanel{Spacing=10};var count=Text("");long request=0;
 async Task Reload(){var ticket=++request;try{var data=await StoreService.Catalog(search.Text??"",(category.SelectedItem as Choice)?.Id??0,sort.SelectedIndex);if(ticket!=request)return;list.Children.Clear();count.Text=$"Найдено товаров: {data.Count}";foreach(var p in data){var panel=new StackPanel{Spacing=5};panel.Children.Add(new TextBlock{Text=p.Title,FontSize=18,FontWeight=FontWeight.Bold});panel.Children.Add(Text($"Код {p.Id} • {p.Category} • {p.Brand} | {p.Price:N2} ₽ | Остаток {p.Stock}"));panel.Children.Add(Button("Подробнее",()=>ProductPage(p)));if(Session.Manage)panel.Children.Add(Button("Изменить",()=>ProductEditor(p)));list.Children.Add(new Border{Child=panel,Padding=new Thickness(14),CornerRadius=new CornerRadius(6),Background=Brush.Parse(p.Stock<=3?"#FFEBEE":"#FFFFFF")});}}catch(Exception ex){if(ticket==request)Message.Text="Не удалось загрузить каталог: "+ex.Message;}}
 Page.Children.Add(search);Page.Children.Add(category);Page.Children.Add(sort);Page.Children.Add(Button("Обновить",Reload));Page.Children.Add(count);Page.Children.Add(list);search.TextChanged+=async(_,_)=>await Reload();category.SelectionChanged+=async(_,_)=>await Reload();sort.SelectionChanged+=async(_,_)=>await Reload();await Reload();}
 Task ProductPage(Product p){Start(p.Title);Page.Children.Add(Text($"{p.Category} / {p.Brand} / поставщик {p.Supplier}"));Page.Children.Add(Text($"Цена {p.Price:N2} ₽. Доступно {p.Stock} шт."));if(Session.Current==null){Page.Children.Add(Text("Для оформления покупки войдите в систему."));return Task.CompletedTask;}var qty=Input("Количество","1");var discount=Input("Скидка 0–30%","0");Page.Children.Add(qty);Page.Children.Add(discount);Page.Children.Add(Button("Добавить в корзину",async()=>{if(!int.TryParse(qty.Text,out int n))throw new ArgumentException("Количество должно быть целым.");if(!decimal.TryParse(discount.Text,out var d))throw new ArgumentException("Введите скидку числом.");PriceRules.Total(p.Price,n,d);if(n>p.Stock)throw new ArgumentException("Недостаточно товара на складе.");if(cart.Any(x=>x.Product.Id==p.Id))throw new ArgumentException("Товар уже в корзине. Удалите старую строку перед изменением.");cart.Add(new CartLine(p,n,d));await Cart();}));return Task.CompletedTask;}
 async Task Cart(){Session.RequireLogin();Start("Корзина и оформление заказа");foreach(var line in cart.ToArray()){var row=new StackPanel{Orientation=Orientation.Horizontal,Spacing=8};row.Children.Add(Text(line.ToString()));row.Children.Add(Button("Убрать",async()=>{cart.Remove(line);await Cart();}));Page.Children.Add(row);}Page.Children.Add(Text($"Итого: {cart.Sum(x=>x.Total):N2} ₽"));var client=new ComboBox{MinWidth=300};if(Session.Staff){var t=await Db.Query("SELECT client_id,full_name FROM Clients WHERE is_active=1 ORDER BY full_name");client.ItemsSource=t.Rows.Cast<DataRow>().Select(r=>new Choice((int)r[0],(string)r[1])).ToList();client.SelectedIndex=0;Page.Children.Add(Text("Покупатель"));Page.Children.Add(client);}Page.Children.Add(Button("Подтвердить заказ",async()=>{var id=await OrderService.Create(cart.ToArray(),Session.Staff?(client.SelectedItem as Choice)?.Id??0:Session.Current!.Id);cart.Clear();await Orders();Message.Text=$"Заказ № {id} оформлен.";}));Page.Children.Add(Button("Очистить корзину",async()=>{cart.Clear();await Cart();}));}
 void Table(DataTable t){var rows=new StackPanel{Spacing=5};rows.Children.Add(new TextBlock{Text=string.Join(" | ",t.Columns.Cast<DataColumn>().Select(x=>x.ColumnName)),FontWeight=FontWeight.Bold,TextWrapping=TextWrapping.Wrap});foreach(DataRow r in t.Rows)rows.Children.Add(Text(string.Join(" | ",r.ItemArray.Select(v=>v is DateTime d?d.ToString("dd.MM.yyyy HH:mm"):v is decimal m?m.ToString("N2"):v?.ToString()))));if(t.Rows.Count==0)rows.Children.Add(Text("Нет записей."));Page.Children.Add(rows);}
 async Task Orders(){Start("История заказов");Table(await OrderService.List());var id=Input("Номер заказа");Page.Children.Add(id);Page.Children.Add(Button("Открыть состав",async()=>{if(!int.TryParse(id.Text,out var n))throw new ArgumentException("Введите номер.");var t=await OrderService.Details(n);Start($"Состав заказа № {n}");Table(t);}));if(Session.Manage)Page.Children.Add(Button("Отменить заказ и вернуть остаток",async()=>{if(!int.TryParse(id.Text,out var n))throw new ArgumentException("Введите номер.");await Confirm("Отменить заказ № "+n+"?",async()=>{await OrderService.Cancel(n);await Orders();});}));}
 Task Confirm(string question,Func<Task> action){Start("Подтверждение действия");Page.Children.Add(Text(question));Page.Children.Add(Button("Да, подтвердить",action));Page.Children.Add(Button("Нет, назад",Catalog));return Task.CompletedTask;}
 async Task ProductEditor(Product? p){Session.RequireManage();Start(p==null?"Новый товар":"Изменение товара");var title=Input("Название",p?.Title??"");var price=Input("Цена",p?.Price.ToString()??"1000");var stock=Input("Остаток",p?.Stock.ToString()??"0");async Task<ComboBox> Combo(string table,int? id){var items=await StoreService.Choices(table);return new ComboBox{ItemsSource=items,SelectedItem=items.FirstOrDefault(x=>x.Id==id)??items.FirstOrDefault(),MinWidth=250};}var category=await Combo("Categories",p?.CategoryId);var brand=await Combo("Manufacturers",p?.ManufacturerId);var supplier=await Combo("Suppliers",p?.SupplierId);foreach(var c in new Control[]{Text("Название"),title,Text("Категория"),category,Text("Производитель"),brand,Text("Поставщик"),supplier,Text("Цена"),price,Text("Остаток"),stock})Page.Children.Add(c);Page.Children.Add(Button("Сохранить",async()=>{if(!decimal.TryParse(price.Text,out var v)||!int.TryParse(stock.Text,out var n))throw new ArgumentException("Цена — число, остаток — целое.");await StoreService.SaveProduct(p?.Id??0,title.Text??"",(category.SelectedItem as Choice)?.Id??0,(brand.SelectedItem as Choice)?.Id??0,(supplier.SelectedItem as Choice)?.Id??0,v,n);await Catalog();}));if(p!=null)Page.Children.Add(Button("Удалить товар",()=>Confirm("Удалить товар "+p.Title+"?",async()=>{await StoreService.DeleteProduct(p.Id);await Catalog();})));}
 Task References(){Session.RequireManage();Start("Справочники");foreach(var item in new[]{("Categories","Категории"),("Manufacturers","Производители"),("Suppliers","Поставщики")})Page.Children.Add(Button(item.Item2,()=>ReferenceEditor(item.Item1,item.Item2)));return Task.CompletedTask;}
 async Task ReferenceEditor(string table,string title){Session.RequireManage();Start(title);var choices=await StoreService.Choices(table);choices.Insert(0,new Choice(0,"Новая запись"));var choice=new ComboBox{ItemsSource=choices,SelectedIndex=0,MinWidth=300};var name=Input("Название");var extra=Input(table=="Categories"?"Описание":table=="Manufacturers"?"Страна":"Телефон");choice.SelectionChanged+=async(_,_)=>{var current=choice.SelectedItem as Choice;name.Text=current?.Id>0?current.Name:"";extra.Text="";if(current?.Id>0){var key=table=="Categories"?"category_id":table=="Manufacturers"?"manufacturer_id":"supplier_id";var field=table=="Categories"?"description":table=="Manufacturers"?"country":"phone";await Run(async()=>{var data=await Db.Query($"SELECT {field} FROM {table} WHERE {key}=@id",("@id",current.Id));extra.Text=data.Rows.Count>0?data.Rows[0][0].ToString():"";});}};Page.Children.Add(choice);Page.Children.Add(name);Page.Children.Add(extra);Page.Children.Add(Button("Сохранить",async()=>{await StoreService.SaveReference(table,(choice.SelectedItem as Choice)?.Id??0,name.Text??"",extra.Text??"");await ReferenceEditor(table,title);}));}
 async Task Users(){Session.RequireAdmin();Start("Управление пользователями");Table(await StoreService.Users());var id=Input("Код для изменения; 0 — новый","0");var name=Input("ФИО");var email=Input("Электронная почта");var phone=Input("Телефон");var password=Input("Новый пароль; пустой — сохранить прежний");password.PasswordChar='●';var roles=new ComboBox{ItemsSource=await StoreService.Choices("Roles"),SelectedIndex=0,MinWidth=250};var active=new CheckBox{Content="Учётная запись активна",IsChecked=true};foreach(var c in new Control[]{id,name,email,phone,password,roles,active})Page.Children.Add(c);Page.Children.Add(Button("Загрузить по коду",async()=>{if(!int.TryParse(id.Text,out var n))throw new ArgumentException("Введите код.");var t=await Db.Query("SELECT * FROM Clients WHERE client_id=@id",("@id",n));if(t.Rows.Count==0)throw new ArgumentException("Пользователь не найден.");var r=t.Rows[0];name.Text=(string)r["full_name"];email.Text=(string)r["email"];phone.Text=r["phone"].ToString();roles.SelectedItem=((List<Choice>)roles.ItemsSource!).First(x=>x.Id==(int)r["role_id"]);active.IsChecked=(bool)r["is_active"];password.Text="";}));Page.Children.Add(Button("Сохранить пользователя",async()=>{if(!int.TryParse(id.Text,out var n)||n<0)throw new ArgumentException("Некорректный код.");await StoreService.SaveUser(n,name.Text??"",email.Text??"",phone.Text??"",(roles.SelectedItem as Choice)?.Id??0,password.Text??"",active.IsChecked==true);await Users();}));}
 Task Report(){Session.RequireManage();Start("Отчёт о продажах");var from=Input("Начало периода дд.мм.гггг",DateTime.Today.AddMonths(-1).ToString("dd.MM.yyyy"));var to=Input("Конец периода дд.мм.гггг",DateTime.Today.ToString("dd.MM.yyyy"));var result=new StackPanel{Spacing=8};Page.Children.Add(from);Page.Children.Add(to);Page.Children.Add(Button("Сформировать",async()=>{if(!DateTime.TryParseExact(from.Text,"dd.MM.yyyy",CultureInfo.InvariantCulture,DateTimeStyles.None,out var a)||!DateTime.TryParseExact(to.Text,"dd.MM.yyyy",CultureInfo.InvariantCulture,DateTimeStyles.None,out var b))throw new ArgumentException("Дата должна иметь вид дд.мм.гггг.");var t=await OrderService.Report(a,b);result.Children.Clear();result.Children.Add(Text(string.Join(" | ",t.Columns.Cast<DataColumn>().Select(x=>x.ColumnName))));foreach(DataRow r in t.Rows)result.Children.Add(Text(string.Join(" | ",r.ItemArray)));result.Children.Add(Text($"Итого выручка: {t.Rows.Cast<DataRow>().Sum(r=>(decimal)r["Выручка"]):N2} ₽"));}));Page.Children.Add(result);return Task.CompletedTask;}
}
